export function mountCaptcha(root,purpose){
 root.className='captcha-panel';root.innerHTML=`<strong>Security check</strong><p>Enter the five digits shown, or use the audio version.</p><img width="320" height="100" alt="Five-digit CAPTCHA. Use the audio control below if needed." hidden><audio controls preload="none" aria-label="Listen to the CAPTCHA digits" hidden></audio><label>Verification code<input inputmode="numeric" autocomplete="off" pattern="[0-9]{5}" maxlength="5" required placeholder="Five digits"></label><button type="button" class="captcha-refresh">New code</button><p role="status" class="captcha-message"></p>`;
 const image=root.querySelector('img'),audio=root.querySelector('audio'),input=root.querySelector('input'),button=root.querySelector('button'),status=root.querySelector('[role=status]');let id='',loading=false;
 async function refresh(){if(loading)return;loading=true;id='';input.value='';button.disabled=true;image.hidden=true;audio.hidden=true;audio.pause();status.textContent='Loading verification…';try{const r=await fetch('/api/bookings?action=captcha&purpose='+purpose,{cache:'no-store',signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Verification unavailable.');id=data.id;image.src=data.image;audio.src=data.audio;image.hidden=false;audio.hidden=false;status.textContent='Code expires after 10 minutes.';}catch(e){status.textContent='Unable to load verification. Select New code to retry.';}finally{loading=false;button.disabled=false;}}
 button.addEventListener('click',refresh);
 return {refresh,ensure:()=>id?Promise.resolve():refresh(),values:()=>({captchaId:id,captchaAnswer:input.value.trim()})};
}
